class AraelError(Exception):
    """A failed solve (status < 0), a caught Rust panic (status -2),
    or a failed covariance query. After a caught panic the model's
    parameters are unchanged and a session in use was invalidated;
    validate() reports the underlying mistake as text.

    Attributes:
        status: the status code.
        message: the last_error text.
        partial: the best accepted LmResult, for a solve that got past
            its first assembly; None otherwise.
        failure: a SolveFailure, the structured cause of a solver
            failure (status -1); None otherwise.
    """

    def __init__(self, status, message, partial=None, failure=None):
        super().__init__("%s (status %d)" % (message, status))
        self.status = int(status)
        self.message = message
        self.partial = partial
        self.failure = failure


