class GpuReport:
    """What a solve did on the GPU it was given, read with LmResult.gpu.

    Attributes:
        backend: GpuBackend, the runtime, as SparseOptions.gpu.
        index: the device, as SparseOptions.gpu_index.
        name: the device's name, as its driver reports it; empty when
            work is UNUSED.
        target: what the kernels were compiled for (sm_89, gfx1036);
            empty when work is UNUSED.
        integrated: whether the GPU shares the host's memory: an
            integrated GPU, or the CPU device. False when work is
            UNUSED.
        wide: GpuWide, the wide scalar: F64 or DF32.
        solve: GpuSolve, how the GPU solved the system.
        f32_system: whether the system the GPU formed and solved is
            f32; otherwise it is in the wide scalar
            (docs/SOLVERS.md#precision).
        work: GpuWork, how much of the solve ran on the GPU.
        host_assembly: HostAssembly, why the host assembled when work
            is SOLVES; NONE otherwise.
        no_device_form: why the model has no device form, when
            host_assembly is NO_DEVICE_FORM; empty otherwise.
        reserved_bytes: the GPU memory its state holds after the solve,
            in use or free, in bytes.
        buffers_created: the GPU buffers its state has allocated over
            its life; unchanged across a solve that allocated nothing.
    """

    __slots__ = ("backend", "index", "name", "target", "integrated", "wide",
                 "solve", "f32_system", "work", "host_assembly",
                 "no_device_form", "reserved_bytes", "buffers_created")

    def __init__(self, raw):
        self.backend = GpuBackend(raw.backend)
        self.index = raw.index
        self.name = (raw.name or b"").decode()
        self.target = (raw.target or b"").decode()
        self.integrated = raw.integrated
        self.wide = GpuWide(raw.wide)
        self.solve = GpuSolve(raw.solve)
        self.f32_system = raw.f32_system
        self.work = GpuWork(raw.work)
        self.host_assembly = HostAssembly(raw.host_assembly)
        self.no_device_form = (raw.no_device_form or b"").decode()
        self.reserved_bytes = raw.reserved_bytes
        self.buffers_created = raw.buffers_created

    def __repr__(self):
        return "GpuReport(" + ", ".join(
            "%s=%r" % (k, getattr(self, k)) for k in self.__slots__) + ")"


