class ParTiming(ctypes.Structure):
    """Where the sweeps' time went (mirror of the Rust ParTiming); all
    zero unless the solve gathered timing, and `on` says which."""
    _fields_ = [
        ("on", ctypes.c_bool),
        ("bind", ctypes.c_double),
        ("assembly_update", ctypes.c_double),
        ("assembly_zero", ctypes.c_double),
        ("assembly", PhaseTiming),
        ("gather_grad", ctypes.c_double),
        ("assembly_zero_vals", ctypes.c_double),
        ("scatter", ctypes.c_double),
        ("cost_update", ctypes.c_double),
        ("cost", PhaseTiming),
    ]


class StoreFootprint(ctypes.Structure):
    """What one store holds (mirror of the Rust StoreFootprint)."""
    _fields_ = [
        ("self_blocks", ctypes.c_uint64),
        ("cross_blocks", ctypes.c_uint64),
        ("coo_entries", ctypes.c_uint64),
        ("bytes", ctypes.c_uint64),
    ]


class PhaseChoice(ctypes.Structure):
    """What one phase's sweeps did over a solve: whether it was
    dispatched over the stores, and how many calls there were."""
    _fields_ = [("threaded", ctypes.c_bool), ("calls", ctypes.c_uint32)]


class SweepReport(ctypes.Structure):
    """What the sweeps did (mirror of the Rust SweepReport). `held` is
    the store count; LmResult.threads_held lists the footprints."""
    _fields_ = [
        ("threads", ctypes.c_uint32),
        ("assembly", PhaseChoice),
        ("cost", PhaseChoice),
        ("timing", ParTiming),
        ("whole", StoreFootprint),
        ("held", ctypes.c_uint32),
    ]


class _OptSweepReport(ctypes.Structure):
    _fields_ = [("has", ctypes.c_bool), ("v", SweepReport)]


class ThreadReport(ctypes.Structure):
    """What a solve's threads did (mirror of the Rust ThreadReport): the
    counts the two halves were given, whether the sweeps fell back to
    one thread, and `sweeps`, None when the model has no threaded sweep
    path."""
    _fields_ = [
        ("sweeps_asked", ctypes.c_uint32),
        ("linear", ctypes.c_uint32),
        ("fell_back", ctypes.c_bool),
        ("_sweeps", _OptSweepReport),
    ]

    sweeps = _plan_opt("_sweeps", lambda v: v)


class AraelVersion(ctypes.Structure):
    """The arael version a shim was built with (mirror of the Rust
    Version): the three numbers and `pre`, the tag after the dash
    ("dev" in 0.9.0-dev, empty for a release). str() gives the
    Cargo.toml form."""
    _fields_ = [
        ("major", ctypes.c_uint32),
        ("minor", ctypes.c_uint32),
        ("patch", ctypes.c_uint32),
        ("_pre", ctypes.c_char_p),
    ]

    @property
    def pre(self):
        return (self._pre or b"").decode()

    def __str__(self):
        s = "%d.%d.%d" % (self.major, self.minor, self.patch)
        return s + "-" + self.pre if self.pre else s


class CovPlan(ctypes.Structure):
    """What a covariance assembly decided (mirror of the Rust CovPlan):
    the `ordering` it kept, what the candidates priced at, how many
    symbolic analyses it built, and whether the block supernodal route
    ran. `candidate_flops` is an (amd, nd) pair, or None when the
    ordering was named outright."""
    _fields_ = [
        ("_ordering", ctypes.c_uint32),
        ("_candidate_flops", _OptCandidateFlops),
        ("symbolics_built", ctypes.c_uint32),
        ("block_route", ctypes.c_bool),
    ]

    candidate_flops = _plan_opt("_candidate_flops", lambda v: (v.amd, v.nd))

    @property
    def ordering(self):
        return CovOrdering(self._ordering)


class SetupTiming(ctypes.Structure):
    """Where a solve's one-time setup went: the parts of
    LmTiming.analysis the sparse backend times, in seconds. A part a
    route does not have is zero; the parts add up to at most the
    analysis.

    Attributes:
        blocks: finding the model's blocks and the ones to marginalize.
        structure: the Hessian's block pattern, the blocks' positions in
            it and, when reducing, the reduced system's pattern.
        gpu_open: on a GPU, opening it: the process's first solve on
            that GPU creates its state; later solves take nothing here.
        ordering: ordering the system that is factorized.
        weighing: pricing the reduced route against the whole system;
            zero when the comparison was skipped.
        factor: the symbolic factorization and the factor's buffers; on
            a GPU, the GPU factor's plan and kernels.
        gpu_plan: on a GPU, setting the reduction up there.
        gpu_layout: on a GPU that assembles, setting the GPU assembly
            up: the model's data written for the GPU, and its kernels.
    """
    _fields_ = [
        ("blocks", ctypes.c_double),
        ("structure", ctypes.c_double),
        ("gpu_open", ctypes.c_double),
        ("ordering", ctypes.c_double),
        ("weighing", ctypes.c_double),
        ("factor", ctypes.c_double),
        ("gpu_plan", ctypes.c_double),
        ("gpu_layout", ctypes.c_double),
    ]


class GpuTiming(ctypes.Structure):
    """The GPU's own time in a GPU solve, in seconds. The host's phases
    show waits, not the GPU's work: with the LM loop on the GPU,
    LmTiming's assembly and cost_eval read near zero and linear_solve
    holds the GPU's assembly and trial cost with its solve.

    Attributes:
        assembly: the linearizations on the GPU, summed; zero when the
            host assembles.
        attempts: the damped attempts on the GPU, summed; when the host
            assembles, from the upload of the Hessian's values.
        assembly_count: the linearizations timed.
        attempt_count: the attempts timed.
        cg: the part of attempts spent in conjugate gradients, the
            waits between their batches included; zero for a solve that
            factorizes.
        cg_rounds: the batches of conjugate-gradient iterations, each a
            wait for the GPU.
    """
    _fields_ = [
        ("assembly", ctypes.c_double),
        ("attempts", ctypes.c_double),
        ("assembly_count", ctypes.c_uint32),
        ("attempt_count", ctypes.c_uint32),
        ("cg", ctypes.c_double),
        ("cg_rounds", ctypes.c_uint32),
    ]


class _OptSetupTiming(ctypes.Structure):
    _fields_ = [("has", ctypes.c_bool), ("v", SetupTiming)]


class _OptGpuTiming(ctypes.Structure):
    _fields_ = [("has", ctypes.c_bool), ("v", GpuTiming)]


class LmTiming(ctypes.Structure):
    """Per-phase wall-clock seconds plus call counts, gathered when
    config.gather_timing is set (LmResult.timing).

        t = result.timing
        if t.gpu is not None:
            print(1e3 * t.gpu.attempts / t.gpu.attempt_count, "ms an attempt")

    Attributes:
        total: the whole solve.
        assembly: the model's residual, Jacobian and Hessian work, over
            all iterations.
        first_assembly: the first of them.
        analysis: the backend's one-time work on the structure: the
            pattern, the ordering, the symbolic factorization.
        linear_solve: the damped numeric factorizations and solves, over
            all attempts.
        first_linear_solve: the first of them.
        cost_eval: the trial-point cost evaluations.
        first_cost_eval: the first of them.
        advance: the post-step re-centering.
        first_advance: the first of them.
        covariance: the covariance assembly the config asked for, after
            the solve and outside total; zero when none was asked.
        setup: SetupTiming, where analysis went; None from a backend
            that times no parts.
        gpu: GpuTiming, the GPU's own time; None without a GPU.
    """
    _fields_ = [
        ("total", ctypes.c_double),
        ("assembly", ctypes.c_double),
        ("first_assembly", ctypes.c_double),
        ("analysis", ctypes.c_double),
        ("linear_solve", ctypes.c_double),
        ("first_linear_solve", ctypes.c_double),
        ("cost_eval", ctypes.c_double),
        ("first_cost_eval", ctypes.c_double),
        ("advance", ctypes.c_double),
        ("first_advance", ctypes.c_double),
        ("assembly_count", ctypes.c_uint32),
        ("analysis_count", ctypes.c_uint32),
        ("linear_solve_count", ctypes.c_uint32),
        ("cost_eval_count", ctypes.c_uint32),
        ("advance_count", ctypes.c_uint32),
        ("covariance", ctypes.c_double),
        ("_setup", _OptSetupTiming),
        ("_gpu", _OptGpuTiming),
    ]

    setup = _plan_opt("_setup", lambda v: v)
    gpu = _plan_opt("_gpu", lambda v: v)


class LmStep(ctypes.Structure):
    """One attempted LM step: the per-attempt timeline behind
    LmResult.steps. A damping retry is its own record, so rejected
    steps and failed factorizations appear too. Durations are
    wall-clock seconds; assembly is charged to the first attempt at
    each linearization (inner == 0), zero on a retry."""
    _fields_ = [
        ("iter", ctypes.c_uint32),
        ("inner", ctypes.c_uint32),
        ("accepted", ctypes.c_bool),
        ("factorization_failed", ctypes.c_bool),
        ("lambda_", ctypes.c_double),
        ("cost", ctypes.c_double),
        ("new_cost", ctypes.c_double),
        ("step_norm", ctypes.c_double),
        ("grad_max", ctypes.c_double),
        ("time", ctypes.c_double),
        ("assembly", ctypes.c_double),
        ("analysis", ctypes.c_double),
        ("linear_solve", ctypes.c_double),
        ("cost_eval", ctypes.c_double),
        ("advance", ctypes.c_double),
    ]


def _opt_property(field):
    """Property mapping a COpt struct field to a float-or-None."""

    def get(self):
        c = getattr(self, field)
        return float(c.v) if c.has else None

    def set(self, value):
        c = getattr(self, field)
        if value is None:
            c.has = False
            c.v = 0.0
        else:
            c.has = True
            c.v = float(value)

    return property(get, set)


def _opt_int_property(field):
    """Property mapping a COpt struct field to an int-or-None."""

    def get(self):
        c = getattr(self, field)
        return int(c.v) if c.has else None

    def set(self, value):
        c = getattr(self, field)
        if value is None:
            c.has = False
            c.v = 0
        else:
            c.has = True
            c.v = int(value)

    return property(get, set)


def _opt_enum_property(field, enum):
    """Property mapping a COpt struct field to an enum member or None."""

    def get(self):
        c = getattr(self, field)
        return enum(c.v) if c.has else None

    def set(self, value):
        c = getattr(self, field)
        if value is None:
            c.has = False
            c.v = 0
        else:
            c.has = True
            c.v = int(value)

    return property(get, set)


def lm_types(fp):
    """The per-precision solver layouts as a dict: fp is
    ctypes.c_float or ctypes.c_double. Field order is the C ABI."""

    class COptF(ctypes.Structure):
        _fields_ = [("has", ctypes.c_bool), ("v", fp)]

    class COptSeconds(ctypes.Structure):
        _fields_ = [("has", ctypes.c_bool), ("v", ctypes.c_double)]

    class COptU32(ctypes.Structure):
        _fields_ = [("has", ctypes.c_bool), ("v", ctypes.c_uint32)]

    class LmIter(ctypes.Structure):
        """One damped attempt, as the observer callback sees it.
        `params`/`params_len` point at the CURRENT parameter vector;
        valid only during the callback."""
        _fields_ = [
            ("iter", ctypes.c_uint32),
            ("inner", ctypes.c_uint32),
            ("accepted", ctypes.c_bool),
            ("factorization_failed", ctypes.c_bool),
            ("cost", fp),
            ("new_cost", fp),
            ("lambda_", fp),
            ("accepted_total", ctypes.c_uint32),
            ("params", ctypes.POINTER(fp)),
            ("params_len", ctypes.c_uint32),
        ]

        def param(self, i):
            return float(self.params[i])

        def param_list(self):
            return [float(self.params[i]) for i in range(self.params_len)]

    observer_fn = ctypes.CFUNCTYPE(ctypes.c_bool, ctypes.c_void_p,
                                   ctypes.POINTER(LmIter))

    class LmConfig(ctypes.Structure):
        """The solver configuration, holding a preset's Rust values: a
        model module's LmConfig() and its presets defaults(),
        conservative(), well_conditioned() and ill_conditioned() fetch
        them. The fields are those of Rust's LmConfig
        (docs/SOLVERS.md), but for the lambda driver, which the preset
        supplies. These differ from Rust's or are particular to it:

        Attributes:
            gradient_tolerance: a float, or None.
            parameter_tolerance: a float, or None.
            predicted_reduction_tolerance: a float, or None.
            min_diagonal: a float, or None.
            time_limit_seconds: Rust's time_limit in seconds, or None.
            assembly_threads: an int, or None.
            max_accepted_iters: an int, or None.
            covariance: a CovMode, the covariance to assemble at the
                solution, or None.
            covariance_ordering: the CovOrdering of that assembly.
            covariance_block_supernodal: the BlockSupernodalMode of
                that assembly.
            observer: a callable, called with an LmIter per damped
                attempt; returning False stops the solve.
            device_observer_params: with the LM loop on a GPU, read the
                parameters back after each accepted step, for the
                observer; off, LmIter.params_len is 0 there.
        """
        _fields_ = [
            ("preset", ctypes.c_uint32),
            ("max_iters", ctypes.c_uint32),
            ("min_iters", ctypes.c_uint32),
            ("patience", ctypes.c_uint32),
            ("num_threads", ctypes.c_uint32),
            ("verbose", ctypes.c_bool),
            ("gather_timing", ctypes.c_bool),
            ("abs_precision", fp),
            ("rel_precision", fp),
            ("initial_lambda", fp),
            ("cost_threshold", fp),
            ("lambda_floor", fp),
            ("_gradient_tolerance", COptF),
            ("_parameter_tolerance", COptF),
            ("_predicted_reduction_tolerance", COptF),
            ("_min_diagonal", COptF),
            ("_time_limit_seconds", COptSeconds),
            ("_observer", observer_fn),
            ("_observer_user", ctypes.c_void_p),
            ("_assembly_threads", COptU32),
            ("_max_accepted_iters", COptU32),
            ("_covariance", COptU32),
            ("covariance_ordering", ctypes.c_uint32),
            ("covariance_block_supernodal", ctypes.c_uint32),
            ("device_observer_params", ctypes.c_bool),
        ]

        gradient_tolerance = _opt_property("_gradient_tolerance")
        parameter_tolerance = _opt_property("_parameter_tolerance")
        predicted_reduction_tolerance = \
            _opt_property("_predicted_reduction_tolerance")
        min_diagonal = _opt_property("_min_diagonal")
        time_limit_seconds = _opt_property("_time_limit_seconds")
        assembly_threads = _opt_int_property("_assembly_threads")
        max_accepted_iters = _opt_int_property("_max_accepted_iters")
        covariance = _opt_enum_property("_covariance", CovMode)

        @property
        def observer(self):
            return getattr(self, "_observer_py", None)

        @observer.setter
        def observer(self, fn):
            # The CFUNCTYPE object must outlive the config (the
            # classic ctypes GC trap) -- kept as an attribute.
            if fn is None:
                self._observer_py = None
                self._observer_keep = None
                self._observer = observer_fn()
                return

            def trampoline(_user, it):
                r = fn(it.contents)
                return r is None or bool(r)

            self._observer_py = fn
            self._observer_keep = observer_fn(trampoline)
            self._observer = self._observer_keep

    class LmResult(ctypes.Structure):
        """A completed solve: costs, iterations, status, damping, and
        (when gathered) the timing breakdown. `_detail` owns the full
        Rust-side result; the generated module's LmResult subclass
        renders reports and the backend plan from it and frees it on
        garbage collection."""
        _fields_ = [
            ("start_cost", fp),
            ("end_cost", fp),
            ("iterations", ctypes.c_uint32),
            ("accepted_iterations", ctypes.c_uint32),
            ("_status", ctypes.c_int32),
            ("final_lambda", fp),
            ("_timing", LmTiming),
            ("has_timing", ctypes.c_bool),
            ("_detail", ctypes.c_void_p),
        ]

        @property
        def status(self):
            return LmStatus(self._status)

        @property
        def timing(self):
            return self._timing if self.has_timing else None

    return {
        "COptF": COptF,
        "COptSeconds": COptSeconds,
        "LmIter": LmIter,
        "LmConfig": LmConfig,
        "LmResult": LmResult,
        "observer_fn": observer_fn,
    }


# Former names, kept as deprecated aliases.
_RENAMED = {"FaerOrdering": "SolveOrdering", "SchurSolve": "SchurMethod"}


def __getattr__(name):
    """FaerOrdering and SchurSolve, the former names of SolveOrdering and
    SchurMethod: the new class, with a DeprecationWarning."""
    new = _RENAMED.get(name)
    if new is None:
        raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
    warnings.warn(f"{name} is renamed to {new}", DeprecationWarning, stacklevel=2)
    return globals()[new]
